const passwordResetTokenSchema = new mongoose.Schema({
  // Stores the ID of the user who initiated the password reset request.
  // This links the token back to a specific user account.
  userId: {
    type: mongoose.Schema.Types.ObjectId,
    required: true,
    ref: 'User', // Establishes a reference to the 'User' model.
  },
  // The actual unique token string generated for the password reset process.
  token: {
    type: String,
    required: true,
  },
  // Timestamp indicating when the token was created.
  // MongoDB will automatically delete this document after the specified 'expires' duration
  // due to the TTL (Time-To-Live) index created by this option.
  createdAt: {
    type: Date,
    default: Date.now, // Defaults to the current date and time when the token is created.
    expires: 3600, // Token expires in 1 hour (adjustable)
  },
});

const petSchema = new mongoose.Schema(
  {
    // Name of the pet.
    name: {
      type: String,
      required: true, // Name is a mandatory field.
      trim: true, // Automatically removes leading/trailing whitespace.
    },
    // Age of the pet in years.
    ageYears: {
      type: Number,
      required: true, // Age in years is mandatory.
      min: 0, // Age cannot be negative.
    },
    // Age of the pet in months (0-11).
    ageMonths: {
      type: Number,
      required: true, // Age in months is mandatory.
      min: 0, // Months cannot be negative.
      max: 11, // Months cannot exceed 11.
    },
    // Weight of the pet.
    weight: {
      type: Number,
      required: true, // Weight is mandatory.
      min: 0, // Weight cannot be negative.
    },
    // Species of the pet, restricted to 'Cat' or 'Dog'.
    species: {
      type: String,
      enum: ['Cat', 'Dog'], // Allowed values for species.
      required: true, // Species is mandatory.
    },
    // Gender of the pet, restricted to 'Male' or 'Female'.
    gender: {
      type: String,
      enum: ['Male', 'Female'], // Allowed values for gender.
      required: true, // Gender is mandatory.
    },
    // Breed of the pet.
    breed: {
      type: String,
      required: true, // Breed is mandatory.
    },
    // Optional medical information about the pet.
    medicalInfo: {
      type: String,
      trim: true, // Automatically removes leading/trailing whitespace.
    },
    // Array of URLs pointing to pictures of the pet.
    pictures: {
      type: [String], // Defines an array of strings.
      default: [], // Defaults to an empty array if no pictures are provided.
    },
    // Reference to the User who owns this pet.
    owner: {
      type: mongoose.Schema.Types.ObjectId, // Stores the ObjectId of the owner.
      ref: 'User', // Establishes a reference to the 'User' model.
      required: true, // Owner is mandatory.
    },
  },
  {
    // Mongoose options:
    timestamps: true, // Automatically adds `createdAt` and `updatedAt` fields.
  },
);

const sentReminderSchema = new mongoose.Schema({
  // Unique key combining rule ID and the specific occurrence start time (as timestamp)
  // This key uniquely identifies a specific instance of a repeating schedule.
  reminderKey: {
    type: String,
    required: true,
    unique: true, // Ensure we don't store duplicates
    index: true, // Index for faster lookups
  },
  // Timestamp when the reminder was sent.
  sentAt: {
    type: Date,
    default: Date.now,
    // Automatically remove documents after, e.g., 2 hours to keep collection clean
    // This prevents the collection from growing indefinitely. Adjust time as needed.
    expires: 7200, // TTL in seconds (2 hours = 2 * 60 * 60)
  },
  // Optional fields for easier debugging/querying - link back to the original schedule rule.
  ruleId: {
    type: mongoose.Schema.Types.ObjectId,
    ref: 'Schedule', // References the Schedule model.
  },
  // Optional field storing the exact start time of the occurrence for which the reminder was sent.
  occurrenceStartTime: {
    type: Date,
  },
  // Optional field storing the email address the reminder was sent to.
  recipientEmail: {
    type: String,
  },
});

